        public string Print(
            IFallout3ModGetter item,
            string? name = null,
            Fallout3Mod.Mask<bool>? printMask = null)
        {
            var sb = new StructuredStringBuilder();
            Print(
                item: item,
                sb: sb,
                name: name,
                printMask: printMask);
            return sb.ToString();
        }
        
        public void Print(
            IFallout3ModGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Fallout3Mod.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Fallout3Mod =>");
            }
            else
            {
                sb.AppendLine($"{name} (Fallout3Mod) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
