                }
                case RecordTypeInts.NOTE:
                {
                    if (importMask?.Notes ?? true)
                    {
                        item.Notes.CopyInFromBinary(
                            frame: frame,
                            translationParams: null);
                    }
                    else
                    {
                        frame.Position += contentLength;
                    }
                    return (int)Fallout3Mod_FieldIndex.Notes;
                }
                default:
                    frame.Position += contentLength;
